#!/usr/bin/env python3
"""Manage the files generated by one FDMNES calculation."""

import shutil
from glob import escape
from pathlib import Path


class FdmResultFiles:
    """Find, clean, rename, or archive files associated with a Filout prefix."""

    def __init__(self, filout: str | Path) -> None:
        """Store the calculation's output prefix.

        Args:
            filout: Filename prefix, optionally preceded by a directory.

        Raises:
            ValueError: If the prefix has no filename component.
        """
        self.filout = Path(filout)
        if not self.filout.name or self.filout.name == "..":
            raise ValueError("Empty or invalid Filout prefix")

    def outputs(self) -> list[Path]:
        """Return existing calculation outputs and auxiliary files."""
        paths = self.move_outputs()
        # Callers may select a run outside the current working directory.
        for name in ("fdmnes_error.txt", "fdm.out", "PBS_log"):
            path = self.filout.parent / name
            if path.is_file() and path not in paths:
                paths.append(path)
        return paths

    def move_outputs(self) -> list[Path]:
        """Return existing XAS, BAV, convolved XAS, and SD files."""
        folder = self.filout.parent
        stem = self.filout.name
        candidates = []
        for suffix in (".txt", "_bav.txt", "_conv.txt"):
            candidates.append(folder / f"{stem}{suffix}")

        # Filout is literal. Only the site suffix can match a pattern.
        candidates.extend(sorted(folder.glob(f"{escape(stem)}_sd*.txt")))
        return [path for path in candidates if path.is_file()]

    def clean(self) -> list[Path]:
        """Delete the result and auxiliary files and return their paths."""
        deleted = []
        for path in self.outputs():
            path.unlink(missing_ok=True)
            deleted.append(path)
        return deleted

    def move(self, destination: str | Path) -> list[Path]:
        """Archive calculation results under their original filenames.

        Args:
            destination: Directory to create or use for the archive.

        Returns:
            Destination paths for the archived files.
        """
        folder = Path(destination)
        folder.mkdir(parents=True, exist_ok=True)
        moved = []
        for path in self.move_outputs():
            target = folder / path.name
            moved_path = shutil.move(str(path), str(target))
            moved.append(Path(moved_path))
        return moved

    def rename(self, destination: str | Path) -> list[Path]:
        """Move calculation outputs to a new Filout prefix as in SAE FDmove.

        Args:
            destination: New prefix, optionally preceded by an existing directory.

        Returns:
            Destination paths in calculation-result order.

        Raises:
            FileExistsError: If a destination already exists.
            OSError: If a file cannot be moved.
            ValueError: If the destination lacks a filename component.
        """
        prefix = Path(destination)
        if not prefix.name or prefix.name == "..":
            raise ValueError("Destination must include a filename prefix")

        pairs = []
        for source in self.move_outputs():
            suffix = source.name[len(self.filout.name) :]
            target = prefix.with_name(prefix.name + suffix)
            if source.resolve() == target.resolve() and not target.is_symlink():
                continue
            if target.exists() or target.is_symlink():
                raise FileExistsError(f"Destination already exists: {target}")
            pairs.append((source, target))

        moved = []
        for source, target in pairs:
            source.rename(target)
            moved.append(target)
        return moved
